import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(this));
        address ownerBefore = c.owner();
        vm.prank(actor);
        bool ok;
        try c.setOwner(newOwner) { ok = true; } catch { ok = false; }
        assertTrue(
            (actor == ownerBefore) == ok &&
            (!ok || c.owner() == newOwner) &&
            (ok || c.owner() == ownerBefore),
            "setOwner must only succeed for owner"
        );
    }
}

