pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0));
        // The deployer (this test contract) is the initial owner; only it can succeed.
        bool ok;
        vm.prank(actor);
        try c.setOwner(newOwner) returns (bool s) {
            ok = s;
        } catch {
            ok = false;
        }
        // General rule: whenever setOwner reports success, the resulting owner
        // is exactly the requested newOwner — ownership moves only where requested.
        assertTrue(!ok || c.owner() == newOwner, "successful setOwner must set owner to the requested newOwner");
    }
}

