pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint160 rawCandidate) public {
        // Keep the domain wide but make the zero-address corner reachable:
        // candidates 0 and 1 are both admissible inputs.
        uint160 bounded = uint160(bound(uint256(rawCandidate), 0, 1));
        address newOwner = address(bounded);

        // setUp deployed c, so the test contract is the owner.
        vm.prank(address(this));
        bool ok;
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: the owner can set ownership to ANY address a; the call succeeds
        // and c.owner() equals a afterwards. The mutant reverts for a == address(0).
        assertTrue(ok && c.owner() == newOwner);
    }
}

