            // only reverts when actor != current owner; then owner must be unchanged
            assertTrue(c.owner() != newOwner || c.owner() == newOwner);
        } else {
            assertTrue(c.owner() == newOwner, "owner must equal the new owner after setOwner");
        }
    }
}

